-- Thirty new Egg cosmetics and eight existing high-price relics, paid only in IntGem.
-- Existing server-saved owners keep their relics without another charge.
alter table private.intgem_items add column if not exists native_id text;
alter table private.intgem_items drop constraint if exists intgem_items_kind_check;
alter table private.intgem_items add constraint intgem_items_kind_check
  check(kind in ('aura','companion') or (game='egg' and kind in ('head','face','back')));
create unique index if not exists intgem_items_native_id_unique
  on private.intgem_items(native_id) where native_id is not null;

do $catalog$
declare first_install boolean := not exists(select 1 from private.intgem_items where id='egg_relic_starBeacon');
begin
 insert into private.intgem_items(id,game,name,kind,rarity,price,color,secondary,description,native_id)
 select id,game,name,kind,rarity,price,color,secondary,description,native_id
 from jsonb_to_recordset($items$[{"id":"egg_station_head","game":"egg","name":"Quepe do Maquinista","kind":"head","price":4,"model":"cap","color":"#32cfc3","secondary":"#ffce64","rarity":"Raro","collection":"Estação Integro","isNew":true,"description":"Quepe turquesa com emblema dourado e aba escura. Cosmético permanente.","native_id":"ig_station_head"},{"id":"egg_station_face","game":"egg","name":"Visor de Trilhos","kind":"face","price":4,"model":"scanner","color":"#32cfc3","secondary":"#ffce64","rarity":"Raro","collection":"Estação Integro","isNew":true,"description":"Visor panorâmico com dois trilhos luminosos. Cosmético permanente.","native_id":"ig_station_face"},{"id":"egg_station_back","game":"egg","name":"Locomotiva de Bolso","kind":"back","price":7,"model":"train","color":"#32cfc3","secondary":"#ffce64","rarity":"Épico","collection":"Estação Integro","isNew":true,"description":"Uma pequena locomotiva com rodas e chaminé nas costas. Cosmético permanente.","native_id":"ig_station_back"},{"id":"egg_station_companion","game":"egg","name":"Robô Bilhete","kind":"companion","price":7,"model":"robot","color":"#32cfc3","secondary":"#ffce64","rarity":"Épico","collection":"Estação Integro","isNew":true,"description":"Robozinho flutuante com antena e braços articulados. Cosmético permanente.","native_id":null},{"id":"egg_station_aura","game":"egg","name":"Trilhos de Luz","kind":"aura","price":4,"model":"tracks","color":"#32cfc3","secondary":"#ffce64","rarity":"Raro","collection":"Estação Integro","isNew":true,"description":"Dois trilhos e travessas de luz acompanham seus passos. Cosmético permanente.","native_id":null},{"id":"egg_coral_head","game":"egg","name":"Coroa de Coral","kind":"head","price":6,"model":"coral","color":"#ff83ad","secondary":"#76e3ed","rarity":"Raro","collection":"Tesouros do Recife","isNew":true,"description":"Ramos de coral rosado e pequenas pérolas azuis. Cosmético permanente.","native_id":"ig_coral_head"},{"id":"egg_coral_face","game":"egg","name":"Máscara Abissal","kind":"face","price":5,"model":"diver","color":"#ff83ad","secondary":"#76e3ed","rarity":"Raro","collection":"Tesouros do Recife","isNew":true,"description":"Lentes de mergulho com tubo e aro de coral. Cosmético permanente.","native_id":"ig_coral_face"},{"id":"egg_coral_back","game":"egg","name":"Concha Imperial","kind":"back","price":8,"model":"shell","color":"#ff83ad","secondary":"#76e3ed","rarity":"Épico","collection":"Tesouros do Recife","isNew":true,"description":"Concha aberta em leque, com uma pérola no centro. Cosmético permanente.","native_id":"ig_coral_back"},{"id":"egg_coral_companion","game":"egg","name":"Axolote Rubi","kind":"companion","price":8,"model":"axolotl","color":"#ff83ad","secondary":"#76e3ed","rarity":"Épico","collection":"Tesouros do Recife","isNew":true,"description":"Axolote voador com seis brânquias de cristal. Cosmético permanente.","native_id":null},{"id":"egg_coral_aura","game":"egg","name":"Maré de Pérolas","kind":"aura","price":5,"model":"bubbles","color":"#ff83ad","secondary":"#76e3ed","rarity":"Raro","collection":"Tesouros do Recife","isNew":true,"description":"Bolhas e pérolas em órbita ao redor do corredor. Cosmético permanente.","native_id":null},{"id":"egg_aurora_head","game":"egg","name":"Tiara Boreal","kind":"head","price":8,"model":"antlers","color":"#a5a3ff","secondary":"#79f0c5","rarity":"Épico","collection":"Expedição Boreal","isNew":true,"description":"Galhos de cristal verde e lilás sobre a cabeça. Cosmético permanente.","native_id":"ig_aurora_head"},{"id":"egg_aurora_face","game":"egg","name":"Óculos Prisma","kind":"face","price":6,"model":"prism","color":"#a5a3ff","secondary":"#79f0c5","rarity":"Raro","collection":"Expedição Boreal","isNew":true,"description":"Duas lentes hexagonais com reflexos da aurora. Cosmético permanente.","native_id":"ig_aurora_face"},{"id":"egg_aurora_back","game":"egg","name":"Asas Boreais","kind":"back","price":10,"model":"wings","color":"#a5a3ff","secondary":"#79f0c5","rarity":"Épico","collection":"Expedição Boreal","isNew":true,"description":"Seis penas facetadas em cada asa. São decorativas. Cosmético permanente.","native_id":"ig_aurora_back"},{"id":"egg_aurora_companion","game":"egg","name":"Coruja Polar","kind":"companion","price":10,"model":"owl","color":"#a5a3ff","secondary":"#79f0c5","rarity":"Épico","collection":"Expedição Boreal","isNew":true,"description":"Coruja com olhos dourados e asas que batem suavemente. Cosmético permanente.","native_id":null},{"id":"egg_aurora_aura","game":"egg","name":"Jardim da Aurora","kind":"aura","price":7,"model":"petals","color":"#a5a3ff","secondary":"#79f0c5","rarity":"Épico","collection":"Expedição Boreal","isNew":true,"description":"Seis pétalas luminosas giram sob seus pés. Cosmético permanente.","native_id":null},{"id":"egg_magma_head","game":"egg","name":"Elmo Magmático","kind":"head","price":10,"model":"horns","color":"#ff7954","secondary":"#ffda6c","rarity":"Épico","collection":"Forja do Vulcão","isNew":true,"description":"Elmo de lava com chifres dourados e crista central. Cosmético permanente.","native_id":"ig_magma_head"},{"id":"egg_magma_face","game":"egg","name":"Máscara Brasa","kind":"face","price":8,"model":"mask","color":"#ff7954","secondary":"#ffda6c","rarity":"Épico","collection":"Forja do Vulcão","isNew":true,"description":"Máscara facetada com presas e detalhes incandescentes. Cosmético permanente.","native_id":"ig_magma_face"},{"id":"egg_magma_back","game":"egg","name":"Reator Vulcânico","kind":"back","price":12,"model":"reactor","color":"#ff7954","secondary":"#ffda6c","rarity":"Lendário","collection":"Forja do Vulcão","isNew":true,"description":"Reator de dois núcleos com jatos de cristal, sem voo. Cosmético permanente.","native_id":"ig_magma_back"},{"id":"egg_magma_companion","game":"egg","name":"Dragão Faísca","kind":"companion","price":12,"model":"dragon","color":"#ff7954","secondary":"#ffda6c","rarity":"Lendário","collection":"Forja do Vulcão","isNew":true,"description":"Dragão pequenino com chifres, cauda e asas flamejantes. Cosmético permanente.","native_id":null},{"id":"egg_magma_aura","game":"egg","name":"Órbita de Lava","kind":"aura","price":8,"model":"fire","color":"#ff7954","secondary":"#ffda6c","rarity":"Épico","collection":"Forja do Vulcão","isNew":true,"description":"Pontas de fogo estilizadas formam uma coroa no chão. Cosmético permanente.","native_id":null},{"id":"egg_lunar_head","game":"egg","name":"Coroa Nebulosa","kind":"head","price":12,"model":"orbit","color":"#9383ef","secondary":"#80dfff","rarity":"Lendário","collection":"Exploradores do Cosmos","isNew":true,"description":"Planetas e órbitas cercam um cristal sobre a cabeça. Cosmético permanente.","native_id":"ig_lunar_head"},{"id":"egg_lunar_face","game":"egg","name":"Visor Saturno","kind":"face","price":10,"model":"saturn","color":"#9383ef","secondary":"#80dfff","rarity":"Épico","collection":"Exploradores do Cosmos","isNew":true,"description":"Uma lente planetária com anéis inclinados. Cosmético permanente.","native_id":"ig_lunar_face"},{"id":"egg_lunar_back","game":"egg","name":"Satélite Portátil","kind":"back","price":16,"model":"satellite","color":"#9383ef","secondary":"#80dfff","rarity":"Lendário","collection":"Exploradores do Cosmos","isNew":true,"description":"Painéis solares, antena e um núcleo de ametista. Cosmético permanente.","native_id":"ig_lunar_back"},{"id":"egg_lunar_companion","game":"egg","name":"Raposa Lunar","kind":"companion","price":14,"model":"fox","color":"#9383ef","secondary":"#80dfff","rarity":"Lendário","collection":"Exploradores do Cosmos","isNew":true,"description":"Raposa com orelhas pontudas e uma grande cauda estelar. Cosmético permanente.","native_id":null},{"id":"egg_lunar_aura","game":"egg","name":"Portais Orbitais","kind":"aura","price":10,"model":"orbit","color":"#9383ef","secondary":"#80dfff","rarity":"Épico","collection":"Exploradores do Cosmos","isNew":true,"description":"Três órbitas cruzadas com pequenos planetas. Cosmético permanente.","native_id":null},{"id":"egg_royal_head","game":"egg","name":"Coroa Diamante","kind":"head","price":14,"model":"crown","color":"#ffd56e","secondary":"#b4e9ff","rarity":"Lendário","collection":"Realeza do Ninho","isNew":true,"description":"Sete pontas douradas e uma grande joia azul. Cosmético permanente.","native_id":"ig_royal_head"},{"id":"egg_royal_face","game":"egg","name":"Monóculo Real","kind":"face","price":12,"model":"monocle","color":"#ffd56e","secondary":"#b4e9ff","rarity":"Lendário","collection":"Realeza do Ninho","isNew":true,"description":"Lente de cristal com corrente e estrela dourada. Cosmético permanente.","native_id":"ig_royal_face"},{"id":"egg_royal_back","game":"egg","name":"Manto Real","kind":"back","price":18,"model":"cape","color":"#ffd56e","secondary":"#b4e9ff","rarity":"Lendário","collection":"Realeza do Ninho","isNew":true,"description":"Manto azul com gola dourada e emblema de diamante. Cosmético permanente.","native_id":"ig_royal_back"},{"id":"egg_royal_companion","game":"egg","name":"Pintinho Imperial","kind":"companion","price":16,"model":"chick","color":"#ffd56e","secondary":"#b4e9ff","rarity":"Lendário","collection":"Realeza do Ninho","isNew":true,"description":"Pintinho coroado, com bico dourado e pequenas asas. Cosmético permanente.","native_id":null},{"id":"egg_royal_aura","game":"egg","name":"Constelação Real","kind":"aura","price":12,"model":"stars","color":"#ffd56e","secondary":"#b4e9ff","rarity":"Lendário","collection":"Realeza do Ninho","isNew":true,"description":"Estrelas e diamantes desenham uma constelação no chão. Cosmético permanente.","native_id":null},{"id":"egg_relic_dragonWings","game":"egg","name":"Asas de dragão","kind":"back","price":14,"color":"#79cfad","secondary":"#ffce6a","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Membranas verdes e hastes douradas. Cosmético permanente.","native_id":"dragonWings"},{"id":"egg_relic_prismHalo","game":"egg","name":"Halo prismático","kind":"head","price":16,"color":"#bca4ff","secondary":"#7ae8df","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Dois anéis de cristal e seis prismas coloridos. Cosmético permanente.","native_id":"prismHalo"},{"id":"egg_relic_timeMask","game":"egg","name":"Máscara dos segundos","kind":"face","price":18,"color":"#7ddbc8","secondary":"#ffd375","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Lente-relógio, ponteiros e engrenagem lateral. Cosmético permanente.","native_id":"timeMask"},{"id":"egg_relic_clockworkCrown","game":"egg","name":"Coroa do tempo","kind":"head","price":20,"color":"#ffcf72","secondary":"#81d9d4","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Relógio cercado por engrenagens douradas. Cosmético permanente.","native_id":"clockworkCrown"},{"id":"egg_relic_hourglassPack","game":"egg","name":"Ampulheta eterna","kind":"back","price":22,"color":"#9ccfff","secondary":"#ffe3a1","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Duas câmaras de cristal e areia luminosa. Cosmético permanente.","native_id":"hourglassPack"},{"id":"egg_relic_galaxyMask","game":"egg","name":"Máscara galáctica","kind":"face","price":24,"color":"#b5a0ff","secondary":"#8de7ff","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Constelações e planetas em um visor violeta. Cosmético permanente.","native_id":"galaxyMask"},{"id":"egg_relic_galaxyPortal","game":"egg","name":"Portal das galáxias","kind":"back","price":26,"color":"#9981e9","secondary":"#ffcf80","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Anéis orbitais, estrelas e uma nebulosa central. Cosmético permanente.","native_id":"galaxyPortal"},{"id":"egg_relic_starBeacon","game":"egg","name":"Farol do infinito","kind":"back","price":28,"color":"#80e8df","secondary":"#ffd977","rarity":"Relíquia","collection":"Relíquias da aventura","converted":true,"description":"Planeta luminoso com três órbitas douradas. Cosmético permanente.","native_id":"starBeacon"}]$items$::jsonb)
 as x(id text,game text,name text,kind text,rarity text,price integer,color text,secondary text,description text,native_id text)
 on conflict(id) do update set name=excluded.name,price=excluded.price,rarity=excluded.rarity,
  color=excluded.color,secondary=excluded.secondary,description=excluded.description,native_id=excluded.native_id;
 if first_install then
  -- Snapshot only once. Later saves cannot claim a paid item retroactively.
  insert into private.intgem_inventory(user_id,item_id)
   select s.user_id,i.id from private.box_egg_saves s cross join private.intgem_items i
   where i.id like 'egg_relic_%' and jsonb_typeof(s.data->'accessories')='array'
     and (s.data->'accessories') ? i.native_id
   on conflict do nothing;
  insert into private.intgem_equipped(user_id,game,kind,item_id)
   select s.user_id,'egg',i.kind,i.id from private.box_egg_saves s
   join private.intgem_inventory owned on owned.user_id=s.user_id
   join private.intgem_items i on i.id=owned.item_id
   where i.id like 'egg_relic_%' and s.data->'equipped'->>i.kind=i.native_id
   on conflict(user_id,game,kind) do nothing;
 end if;
end $catalog$;

do $capabilities$
declare body text;
begin
 body:=pg_get_functiondef('public.box_egg(text,integer,jsonb,uuid,integer,uuid,text,text,integer)'::regprocedure);
 if position('''accessories'',64' in body)>0 then
  execute replace(body,'''accessories'',64','''accessories'',82');
 elsif position('''accessories'',82' in body)=0 then
  raise exception 'egg_capabilities_version_mismatch';
 end if;
end $capabilities$;
